def digest(path): return hashlib.sha256(Path(path).read_bytes()).hexdigest()
def main():
    parser=argparse.ArgumentParser(description=__doc__)
    parser.add_argument('--output',type=Path,required=True)
    parser.add_argument('--curl-profile',type=Path,default=SPIKE/'native-curl-profile-experiment-1')
    parser.add_argument('--archive-profile',type=Path,default=SPIKE/'native-libarchive-lzma-experiment-1')
    parser.add_argument('--mbedtls-source',type=Path,default=SPIKE/'mbedtls-068ff080b369adfac81509f9b57b2afabaf82dc5')
    parser.add_argument('--archive',type=Path,default=SPIKE/'nexus-download-jobs-1/fixture.zip')
