    profile=args.curl_profile.resolve();codecs=args.archive_profile.resolve();mbed=args.mbedtls_source.resolve()
    common=['-Wall','-Wextra','-Werror','-g','-O1','-I',HOST,'-I',ROOT/'outputs/ps5-mod-bridge/include','-isystem',ROOT/'outputs/ps5-mod-bridge/third_party']
    cdefs=['-DMB_ARCHIVE_BUILTIN_XZ=1','-DMBEDTLS_CONFIG_FILE="tls_config.h"','-I',SPIKE/'libarchive-release/libarchive','-I',profile,'-I',mbed/'include','-I',mbed/'library','-include',mbed/'library/common.h','-include',profile/'tls_effective.h']
