    cpppaths=[HOST/(name+'.cpp') for name in ['jobs','auth','analysis','nexus_client','nexus_bridge','nexus_download']]+[ROOT/'outputs/ps5-mod-bridge/src/nexus.cpp']
    libs=[codecs/'host/libarchive-build/.libs/libarchive.a',codecs/'host/xz-build/src/liblzma/.libs/liblzma.a',SPIKE/'native-zip-experiment-1/host/zlib-build/libz.a',profile/'host/libmbedcrypto.a']
    headers=[HOST/(name+'.h') for name in ['jobs','auth','nexus_download','analysis','nexus_client','nexus_bridge']]+[ROOT/'outputs/ps5-mod-bridge/include/modbridge/nexus.hpp']
    paths=cpaths+cpppaths+headers+libs+[Path(__file__).resolve(),args.archive.resolve()]
    before={str(p):digest(p) for p in paths};commands=[]
